// === Tab: mySketch ===
let vs = `
   precision highp float;
   precision highp int;

   attribute vec3 aPosition;
   attribute vec2 aTexCoord;

   varying vec2 vTexCoord;

   uniform mat4 uProjectionMatrix;
   uniform mat4 uModelViewMatrix;

    void main() {
      vec4 positionVec4 = vec4(aPosition, 1.0);
      gl_Position = uProjectionMatrix * uModelViewMatrix * positionVec4;
      vTexCoord = aTexCoord;
   }
`;

let fs = `
   precision highp float;
   precision highp int;

   varying vec2 vTexCoord;

   uniform sampler2D u_tex;
   uniform float u_time;

   float pi = 3.14159265358979;

   float rand(vec2 co) {
     float a = fract(dot(co, vec2(2.067390879775102, 12.451168662908249))) - 0.5;
     float s = a * (6.182785114200511 + a * a * (-38.026512460676566 + a * a * 53.392573080032137));
     float t = fract(s * 43758.5453);
     return t;
   }

   void main() {
      vec2 uv0 = 2.0*vTexCoord - 1.0;
      vec2 uv = vTexCoord;
      uv.x += 0.3 * cos(uv.y*pi*3.0 + u_time);
      uv.y += 0.3 * sin(uv.x*pi*3.0 + u_time);

      uv.x += 0.1 - 0.05 / length(vec2(0.2, 0.0) - uv0);
      uv.y += 0.1 - 0.05 / length(vec2(0.0, 0.2) - uv0);

      float radius = 0.015;
      uv.x = uv.x + rand(uv)*radius*0.8 ;
      uv.y = uv.y + rand(uv.yx)*radius*0.8 ;
      vec4 tex = texture2D(u_tex, uv);

      float bin = 0.07;
      vec4 tex_c;
      tex_c = texture2D(u_tex, uv+vec2(bin, 0.0));
      tex.r += (tex_c.r > 0.7) ? tex_c.r * 0.4 : 0.0;
      tex_c = texture2D(u_tex, uv+vec2(0.0, bin));
      tex.g += (tex_c.g > 0.7) ? tex_c.g * 0.4 : 0.0;
      tex_c = texture2D(u_tex, uv+vec2(-bin, 0.0));
      tex.b += (tex_c.b > 0.7) ? tex_c.b * 0.4 : 0.0;

      float tra = ((tex.r+tex.g+tex.b) < 0.1) ? 0.0 : 0.75 ;
      gl_FragColor = tex * vec4(1.0, 1.0, 1.0, tra);
    }
`;

const w = 1112;
let theShader ;
let pg0 = new Array(4);
let pg1 = new Array(4);

function setup() {
   setAttributes("alpha", false);
   setAttributes("antialias", true);
   setAttributes("powerPreference", "high-performance");

   createCanvas(w, w*.75, WEBGL);

   rectMode(CENTER);
   imageMode(CENTER);
   textureMode(NORMAL);
   colorMode(HSB);
   noStroke();

   theShader = createShader(vs, fs);
   for(let i=0;i<4;i++){
      pg0[i] = createGraphics(w*1.75, w*1.75);
      pg1[i]  = createGraphics(w*1.75, w*1.75);
   }

   noLoop();
}

function draw(){
   background(200, 80, 30);

   fill(0, 0, 0, 0);

   for(let i=0;i<4;i++){
      rotate(PI/2*i);

      set_pg1(pg1[i]);
      shader(theShader);
      theShader.setUniform(`u_tex`, pg1[i]);
      push();
      rotate(PI/4);
      rect(0, -w*0.5, w*0.75, w*1.5);
      pop();

      set_pg0(pg0[i]);

      shader(theShader);
      theShader.setUniform(`u_tex`, pg0[i]);
      theShader.setUniform(`u_time`, random(300) + i);

      rect(0, -w*0.1, w*1.0, w*1.0);
   }

}


function set_pg1(in_pg){
   in_pg.colorMode(HSB);
   const pgw = in_pg.width/2;
   const pgr = in_pg.width/20;
   let px, py;
   in_pg.background(0);
   in_pg.noStroke();

   let wnum = 10;

   for(let i=0;i<wnum;i++){
      let hnum = int(random(1, 10));
      for(let j=0;j<hnum;j++){
         let fc = color( randomGaussian(160, 90),
                         randomGaussian(80, 50),
                         randomGaussian(100, 40));
         in_pg.fill(fc);

         px = pgw-pgr + randomGaussian(0, pgw/3);
         py = pgw-pgr + randomGaussian(0, pgw/3) ;
         in_pg.ellipse(px, py, pgr, pgr);
      }
   }
}

function set_pg0(in_pg){
   in_pg.colorMode(HSB);
   var pgw = in_pg.width/2;
   var pgr = in_pg.width/16;
   var px, py;
   in_pg.background(0);
   in_pg.noStroke();

   var wnum = 10;

   for(let i=0;i<wnum;i++){
      var hnum = int(random(1, 10));
      for(let j=0;j<hnum;j++){
         var fc = color( randomGaussian(260, 60),
                         randomGaussian(80, 50),
                         randomGaussian(100, 20));
         in_pg.fill(fc);
         px = randomGaussian(pgw, pgw) ;
         py = pgw/5 + randomGaussian(0, pgw/5);
         in_pg.rect(px, py, pgr, pgr);
         in_pg.rect(-px, py, pgr, pgr);
      }
   }
}

//save jpg
let lapse = 0;    // mouse timer
function mousePressed(){
  // prevents mouse press from registering twice
  if (millis() - lapse > 400){
    save("img_" + month() + day() + hour() + minute() + second() + ".jpg");
    lapse = millis();
  }
}

